#!/usr/bin/env python3
"""FS3 v135 - the top bar speaks for itself.

PICKUPS
  "+1 CRUISER TICKET" and the like no longer appear in the field. What was
  picked up lights up where it lands, in the bar:
  - a ticket: its symbol and count, in the ticket grid,
  - an extra life: the LIVES symbol and number,
  - a hull repair: the HULL bar, with a green wash over it.
  The light is the kit's glow ring, pulsing softly three times - not the
  old hard blink. A pickup that changes nothing (a repair at full hull, a
  life at the maximum) still lights up, but dimmed, so it is clear it was
  caught.
  The same goes for the ticket a mission hands out for an escort brought
  through - it used to appear in the middle of the field - and for three
  tickets folded into one of the next class.

BUTTONS
  When an allied corvette arrives, the REARM button calls attention to
  itself; when a destroyer arrives, the SHIP SWITCH button does. Four soft
  pulses of the glow ring, on top of its usual 'ready' state. Also when a
  new hull or weapon becomes available while such a ship is on the field,
  because that is the same news: something can now be done here.

Needs v134. Edits src/40_world.js, src/60_effects.js and src/70_ui.js in
place, and writes the updated shipsim.js, hudsim.js and fieldsim.js. Run assemble.py afterwards.
"""
import sys


def replace_once(text, old, new, label):
    n = text.count(old)
    if n != 1:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet einmal." % (label, n))
    return text.replace(old, new)


def load(p):
    return open(p, encoding="utf-8").read()


wo = load("src/40_world.js")
fx = load("src/60_effects.js")
ui = load("src/70_ui.js")

# ══ The pulse itself ═══════════════════════════════════════════════════
ui = replace_once(
    ui,
    "function drawHUD(){\n",
    "// ── BAR PULSE ────────────────────────────────────────────────\n"
    "// Something in the bar calls attention to itself: soft pulses of the\n"
    "// kit's glow ring, n of them over t steps. weak: the same, dimmed - a\n"
    "// pickup that changed nothing. Keys: 'hull', 'lives', 'swap', 'rearm',\n"
    "// 'ticket:<kind>'. Game steps, so a pause holds them.\n"
    "const BAR_PULSE_T = 150, BAR_PULSE_N = 3;      // pickups\n"
    "const BAR_CALL_T  = 240, BAR_CALL_N  = 4;      // a button that can now be used\n"
    "const BAR_WEAK    = 0.4;\n"
    "let BAR_PULSE = {};\n"
    "function barPulse(key, weak, t, n){\n"
    "  BAR_PULSE[key] = {t0:fc, weak:!!weak, t:t||BAR_PULSE_T, n:n||BAR_PULSE_N};\n"
    "}\n"
    "function barPulseLevel(key){\n"
    "  const p = BAR_PULSE[key];\n"
    "  if(!p) return 0;\n"
    "  const age = fc - p.t0;\n"
    "  if(age >= p.t){ delete BAR_PULSE[key]; return 0; }\n"
    "  const v = 0.5 - 0.5*Math.cos(age/p.t*Math.PI*2*p.n);\n"
    "  return v * (p.weak ? BAR_WEAK : 1);\n"
    "}\n"
    "// A button becoming usable is news once, when it happens - not every\n"
    "// step it stays usable.\n"
    "let barSwapWas = false, barRearmWas = false;\n"
    "function tickBarAttention(){\n"
    "  if(GS!=='playing' || FS1_MODE){ barSwapWas = false; barRearmWas = false; return; }\n"
    "  const s = shipSwapReady(), r = rearmReady();\n"
    "  if(s && !barSwapWas)  barPulse('swap',  false, BAR_CALL_T, BAR_CALL_N);\n"
    "  if(r && !barRearmWas) barPulse('rearm', false, BAR_CALL_T, BAR_CALL_N);\n"
    "  barSwapWas = s; barRearmWas = r;\n"
    "}\n"
    "function drawHUD(){\n",
    "bar pulse")

# ── Hull ───────────────────────────────────────────────────────────────
ui = replace_once(
    ui,
    "  ctx.fillRect(hx, hy+11, (hw*hR)|0, hh);\n"
    "  ctx.globalAlpha=1;\n"
    "  thBevel(hx, hy+11, hw, hh);\n",
    "  ctx.fillRect(hx, hy+11, (hw*hR)|0, hh);\n"
    "  ctx.globalAlpha=1;\n"
    "  thBevel(hx, hy+11, hw, hh);\n"
    "  var hPl=barPulseLevel('hull');\n"
    "  if(hPl>0){\n"
    "    ctx.fillStyle='rgba(77,255,136,'+(0.35*hPl).toFixed(3)+')';\n"
    "    ctx.fillRect(hx, hy+11, hw, hh);\n"
    "    thGlowPath(hx-3, hy+8, hw+6, hh+6, 3, hPl);\n"
    "  }\n",
    "hull pulse")

# ── Lives ──────────────────────────────────────────────────────────────
ui = replace_once(
    ui,
    "  ctx.fillStyle=TH('textBright'); ctx.font=thValue(15, true);\n"
    "  ctx.fillText(String(lives), lx+usedW+7, lsy+2);\n",
    "  ctx.fillStyle=TH('textBright'); ctx.font=thValue(15, true);\n"
    "  ctx.fillText(String(lives), lx+usedW+7, lsy+2);\n"
    "  var lPl=barPulseLevel('lives');\n"
    "  if(lPl>0) thGlowPath(lx-5, 5, 88, H2-10, 4, lPl);\n",
    "lives pulse")

# ── Tickets ────────────────────────────────────────────────────────────
ui = replace_once(
    ui,
    "      var fresh=(ticketFlash>0 && ticketFlashKind===tk && fc%16<10);\n"
    "      var col=fresh?TH('accentWarm'):(lit?TH('accent'):TH('textDim'));\n",
    "      var tPl=barPulseLevel('ticket:'+tk);\n"
    "      var col=(tPl>0.3)?TH('accentWarm'):(lit?TH('accent'):TH('textDim'));\n",
    "ticket colour")
ui = replace_once(
    ui,
    "      var tcx=tkX+(ti%2)*tkW, tcy=tkY+((ti/2)|0)*tkH;\n",
    "      var tcx=tkX+(ti%2)*tkW, tcy=tkY+((ti/2)|0)*tkH;\n"
    "      if(tPl>0) thGlowPath(tcx-4, tcy+2, tkW-6, tkH-2, 3, tPl);\n",
    "ticket pulse")

# ── Ship switch and rearm ──────────────────────────────────────────────
ui = replace_once(
    ui,
    "    thButton(swX, swY, swW, swH, (shipMenu||swHv)?'on':(swOn?'ready':null));\n",
    "    thButton(swX, swY, swW, swH, (shipMenu||swHv)?'on':(swOn?'ready':null));\n"
    "    var swPl=barPulseLevel('swap');\n"
    "    if(swPl>0) thGlowPath(swX-3, swY-2, swW+6, swH+4, 5, swPl);\n",
    "swap pulse")
ui = replace_once(
    ui,
    "    thButton(rmX, swY, swW, swH, (rearmMenu||rmHv)?'on':(rmOn?'ready':null));\n",
    "    thButton(rmX, swY, swW, swH, (rearmMenu||rmHv)?'on':(rmOn?'ready':null));\n"
    "    var rmPl=barPulseLevel('rearm');\n"
    "    if(rmPl>0) thGlowPath(rmX-3, swY-2, swW+6, swH+4, 5, rmPl);\n",
    "rearm pulse")

# ══ Pickups light the bar instead of writing into the field ════════════
wo = replace_once(
    wo,
    "        if(it.kind==='repair'){\n"
    "          player.hp = Math.min(player.maxHp, player.hp + player.maxHp*REPAIR_PCT);\n"
    "        } else if(it.kind==='life'){\n"
    "          lives = Math.min(LIVES_MAX, lives+1);\n"
    "        } else {\n"
    "          tickets[it.kind] = (tickets[it.kind]||0) + 1;\n"
    "          STATS.ticketsEarned++;\n"
    "          ticketFlash = 90; ticketFlashKind = it.kind;\n"
    "        }\n"
    "        // Say what was collected, in words. A row of two letter\n"
    "        // abbreviations is not enough to tell CV from DE at a glance.\n"
    "        TICKET_MSGS.push({x:it.x, y:it.y, kind:it.kind, life:150, ml:150,\n"
    "                          rep:(it.kind==='repair'||it.kind==='life')});\n",
    "        // What was collected lights up where it lands, in the bar. A\n"
    "        // pickup that changes nothing still shows, dimmed.\n"
    "        if(it.kind==='repair'){\n"
    "          barPulse('hull', player.hp >= player.maxHp);\n"
    "          player.hp = Math.min(player.maxHp, player.hp + player.maxHp*REPAIR_PCT);\n"
    "        } else if(it.kind==='life'){\n"
    "          barPulse('lives', lives >= LIVES_MAX);\n"
    "          lives = Math.min(LIVES_MAX, lives+1);\n"
    "        } else {\n"
    "          tickets[it.kind] = (tickets[it.kind]||0) + 1;\n"
    "          STATS.ticketsEarned++;\n"
    "          ticketFlash = 90; ticketFlashKind = it.kind;\n"
    "          barPulse('ticket:'+it.kind);\n"
    "        }\n",
    "pickups")

wo = replace_once(
    wo,
    "  ticketFlash = 90; ticketFlashKind = up;\n"
    "  return true;\n",
    "  ticketFlash = 90; ticketFlashKind = up;\n"
    "  barPulse('ticket:'+up);\n"
    "  return true;\n",
    "refine pulse")

fx = replace_once(
    fx,
    "        ticketFlash=120; ticketFlashKind=guardReward;\n"
    "        TICKET_MSGS.push({x:W/2,y:H/2,kind:guardReward,life:190,ml:190,rep:false});\n",
    "        ticketFlash=120; ticketFlashKind=guardReward;\n"
    "        // In the bar, where it lands - no longer in the middle of the field.\n"
    "        barPulse('ticket:'+guardReward);\n",
    "guard reward")

fx = replace_once(
    fx,
    "  tickWeaponUnlocks();\n",
    "  tickWeaponUnlocks();\n"
    "  tickBarAttention();\n",
    "update: attention")

fx = replace_once(
    fx,
    "  ITEMS=[];ticketFlash=0;TICKET_MSGS=[];SUB_MSGS=[];\n",
    "  ITEMS=[];ticketFlash=0;TICKET_MSGS=[];SUB_MSGS=[];BAR_PULSE={};\n",
    "new run: pulses")

open("src/40_world.js", "w", encoding="utf-8").write(wo)
open("src/60_effects.js", "w", encoding="utf-8").write(fx)
open("src/70_ui.js", "w", encoding="utf-8").write(ui)

